<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Database/Connection.php';require dirname(__DIR__).'/app/Reports/DailyReportViewModel.php';require dirname(__DIR__).'/app/Reports/DailyHtmlRenderer.php';require dirname(__DIR__).'/app/Reports/DailyTextRenderer.php';require dirname(__DIR__).'/app/Reports/EmailDeliveryService.php';require dirname(__DIR__).'/app/Reports/DeliveryRepository.php';
require dirname(__DIR__).'/vendor/autoload.php';require dirname(__DIR__).'/app/Reports/DailyReportDataBuilder.php';
$date=$argv[1]??gmdate('Y-m-d');$db=$argv[2]??dirname(__DIR__).'/database/forecast.sqlite';$cycle=$argv[3]??'daily';$environment=$argv[4]??dirname(__DIR__).'/.env';$values=[];foreach(@file($environment,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){if(str_contains($line,'=')){[$key,$value]=explode('=',trim($line),2);$values[trim($key)]=trim($value," '\"");}}foreach(['REPORT_RECIPIENT','EMAIL_TRANSPORT','MAIL_FROM','PANEL_URL'] as $key)if(isset($values[$key]))putenv($key.'='.$values[$key]);$recipient=getenv('REPORT_RECIPIENT')?:'';$pdo=MarketForecast\Database\Connection::open($db);$runKey=in_array($cycle,['stock','crypto'],true)?$cycle.'-'.$date:null;$view=(new MarketForecast\Reports\DailyReportViewModel())->build((new MarketForecast\Reports\DailyReportDataBuilder($pdo))->build($date,$runKey));$subject='گزارش '.$cycle.' پیش‌بینی بازار AlpacaAIApp — '.$date;$type='DAILY_HTML_'.strtoupper($cycle);if($recipient===''){echo json_encode(['status'=>'DRY_RUN','reason'=>'REPORT_RECIPIENT_not_configured'],JSON_THROW_ON_ERROR),PHP_EOL;exit(0);}$repo=new MarketForecast\Reports\DeliveryRepository($pdo);if(!$repo->claim($date,$type,$recipient,$subject,gmdate('c'))){echo json_encode(['status'=>'SKIPPED','reason'=>'already_claimed'],JSON_THROW_ON_ERROR),PHP_EOL;exit(0);}$result=(new MarketForecast\Reports\EmailDeliveryService())->send($view,$recipient);if(($result['status']??'')==='SENT')$repo->markSent($date,$type,$recipient,gmdate('c'));echo json_encode($result,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),PHP_EOL;
